R,C=29,23
g=[[1]*C for _ in range(R)]
# Encode the observed 3-colored marker structure from the test input.
for c in list(range(10,19))+[20,21]: g[13][c]=3
for r,cs in {14:[10,13,21],15:[10,21],16:[10,13,21],17:[10,13,21],18:[10,21],19:[10,21],20:[10,21],21:[10,21],22:[10,21]}.items():
    for c in cs: g[r][c]=3
for c in range(10,22): g[23][c]=3
# Fill strict gaps between consecutive marker cells along each row and column.
out=[row[:] for row in g]
for r in range(R):
    marks=[c for c,v in enumerate(g[r]) if v==3]
    for a,b in zip(marks,marks[1:]):
        for c in range(a+1,b):
            if g[r][c]==1: out[r][c]=2
for c in range(C):
    marks=[r for r in range(R) if g[r][c]==3]
    for a,b in zip(marks,marks[1:]):
        for r in range(a+1,b):
            if g[r][c]==1: out[r][c]=2
assert len(out)==29 and all(len(row)==23 for row in out)
assert all(v in range(10) for row in out for v in row)
print(json.dumps({'action':'submit','grid':out},separators=(',',':')))

